-- Degree planner: the course catalog and each major's suggested plan (edited by admins), and each
-- signed-in student's own saved plan. Seeded from the department's 2025-2026 catalog.

create table public.planner_courses (
  id text primary key check (id ~ '^[A-Za-z0-9_-]{1,20}$'),
  code text not null check (char_length(code) between 1 and 20),
  title text not null check (char_length(title) between 1 and 200),
  credits smallint not null check (credits between 0 and 12),
  prerequisites text[] not null default '{}' check (cardinality(prerequisites) <= 30),
  corequisites text[] not null default '{}' check (cardinality(corequisites) <= 30),
  offered text[] not null default '{}' check (offered <@ array['fall', 'spring', 'summer']),
  description text check (description is null or char_length(description) <= 1000),
  updated_at timestamptz not null default now()
);

create table public.planner_degrees (
  id text primary key check (id ~ '^[A-Za-z0-9_-]{1,40}$'),
  name text not null check (char_length(name) between 1 and 200),
  degree text not null default '' check (char_length(degree) <= 100),
  total_credits smallint not null check (total_credits between 0 and 300),
  catalog_url text check (catalog_url ~ '^https://[^ ]+$'),
  auto_generated boolean not null default false,
  sort_order smallint not null default 0,
  -- [{year, term, note, entries: [{course} | {slot, credits}]}]
  semesters jsonb not null check (jsonb_typeof(semesters) = 'array' and pg_column_size(semesters) < 100000),
  updated_at timestamptz not null default now()
);

create table public.planner_plans (
  user_id uuid primary key references auth.users on delete cascade,
  state jsonb not null check (jsonb_typeof(state) = 'object' and pg_column_size(state) < 200000),
  updated_at timestamptz not null default now()
);

create trigger set_updated_at before update on public.planner_courses
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.planner_degrees
  for each row execute function private.set_updated_at();
create trigger set_updated_at before update on public.planner_plans
  for each row execute function private.set_updated_at();

alter table public.planner_courses enable row level security;
alter table public.planner_degrees enable row level security;
alter table public.planner_plans enable row level security;

-- New tables start with every privilege for the API roles; keep only what is needed.
revoke all on public.planner_courses, public.planner_degrees, public.planner_plans from anon, authenticated;
grant select on public.planner_courses, public.planner_degrees to anon, authenticated;
grant insert, update, delete on public.planner_courses, public.planner_degrees to authenticated;
grant select, insert, update, delete on public.planner_plans to authenticated;

create policy "The catalog is public" on public.planner_courses for select to anon, authenticated using (true);
create policy "Admins manage courses" on public.planner_courses for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

create policy "Suggested plans are public" on public.planner_degrees for select to anon, authenticated using (true);
create policy "Admins manage suggested plans" on public.planner_degrees for all to authenticated
  using ((select private.is_admin())) with check ((select private.is_admin()));

create policy "People manage their own plan" on public.planner_plans for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));


